    public function checkHealth(string $id):array{
        $site=$this->one('SELECT url FROM hub_sites WHERE id=?',[$id]);if(!$site)throw new LifeOSConnectorError(404,'Site not found.');try{$r=LifeOSHubHttp::send($site['url']);$row=['http_status'=>$r['status'],'latency_ms'=>$r['latency_ms'],'ssl_expires'=>$r['ssl_expires'],'error'=>''];}catch(Throwable){$row=['http_status'=>null,'latency_ms'=>null,'ssl_expires'=>null,'error'=>'Site could not be reached securely.'];}$this->run('INSERT INTO hub_health(site_id,http_status,latency_ms,ssl_expires,error) VALUES (?,?,?,?,?)',[$id,...array_values($row)]);return $this->one('SELECT * FROM hub_health WHERE site_id=? ORDER BY id DESC LIMIT 1',[$id]);
    }
    private function upload(string $site,array $file,string $actor):array{
        if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_string($file['tmp_name']??null)||!is_uploaded_file($file['tmp_name']))throw new LifeOSConnectorError(422,'Choose a file.');$bytes=filesize($file['tmp_name']);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);if($bytes<1||$bytes>5*1024*1024||!in_array($mime,['image/jpeg','image/png','image/webp','image/gif','application/pdf','video/mp4'],true))throw new LifeOSConnectorError(422,'Use JPG, PNG, WebP, GIF, PDF or MP4 up to 5 MB.');$name=basename(str_replace('\\','/',self::text($file['name']??'upload',200,true)));$id=bin2hex(random_bytes(16));$storage=$id.'.bin';$dir=dirname($this->path).'/hub-media';if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException('Cannot prepare media storage.');$target=$dir.'/'.$storage;$sha=hash_file('sha256',$file['tmp_name']);if(!move_uploaded_file($file['tmp_name'],$target))throw new RuntimeException('Upload failed.');@chmod($target,0600);
        try{$this->tx(function()use($site,$id,$name,$mime,$bytes,$sha,$storage,$actor){$this->run('INSERT INTO hub_media(id,site_id,filename,mime,bytes,sha256,storage_name) VALUES (?,?,?,?,?,?,?)',[$id,$site,$name,$mime,$bytes,$sha,$storage]);$this->audit($site,$actor,'media.uploaded',$id);});}catch(Throwable $e){unlink($target);throw $e;}return ['id'=>$id,'filename'=>$name,'mime'=>$mime,'bytes'=>$bytes,'url'=>$this->base.'/public/media/'.$id.'/'.$sha];
    }
    public function publicMedia(string $id,string $sha):array{
        $file=$this->one('SELECT * FROM hub_media WHERE id=? AND sha256=?',[$id,$sha]);if(!$file||!$this->one('SELECT slug FROM hub_pages WHERE site_id=? AND instr(published,?)>0 LIMIT 1',[$file['site_id'],$id]))throw new LifeOSConnectorError(404,'Published media not found.');$path=dirname($this->path).'/hub-media/'.$file['storage_name'];if(!is_file($path)||!hash_equals($file['sha256'],hash_file('sha256',$path)))throw new LifeOSConnectorError(503,'Media file unavailable.');return [...$file,'path'=>$path];
    }
    public function publicSite(string $id):array{$site=$this->one('SELECT id,name FROM hub_sites WHERE id=?',[$id]);if(!$site)throw new LifeOSConnectorError(404,'Site not found.');return [...$site,'pages'=>array_map(fn($page)=>[...$page,'fields'=>json_decode($page['published'],true,48,JSON_THROW_ON_ERROR)],$this->all('SELECT slug,published,published_version FROM hub_pages WHERE site_id=? AND published IS NOT NULL ORDER BY slug',[$id]))];}
    public function work(int $limit=10):int{
        $count=0;for($i=0;$i<$limit;$i++){
            $job=$this->tx(function(){$job=$this->one("SELECT * FROM hub_deployments WHERE status IN ('queued','building') AND delivery IN ('pending','retry','sent') AND next_attempt<=? AND locked_until<? ORDER BY created_at LIMIT 1",[time(),time()]);if($job)$this->run('UPDATE hub_deployments SET locked_until=? WHERE id=?',[time()+90,$job['id']]);return $job;});if(!$job)break;$site=$this->one('SELECT * FROM hub_sites WHERE id=?',[$job['site_id']]);
            try{
                $event=['event'=>'content.published','site_id'=>$site['id'],'page'=>$job['page'],'version'=>(int)$job['version'],'deployment_id'=>$job['id']];$body=json_encode($event,JSON_THROW_ON_ERROR);$timestamp=(string)time();$secret=$this->unseal($site['secret'],$site['id']);
                if($job['delivery']!=='sent')foreach(array_filter([$site['webhook_url'],$site['deploy_hook_url']]) as $url){$signature=hash_hmac('sha256',$timestamp.'.'.$body,$secret);$response=LifeOSHubHttp::send($url,'POST',$body,['Content-Type: application/json','X-LifeOS-Timestamp: '.$timestamp,'X-LifeOS-Event: '.$job['id'],'X-LifeOS-Signature: sha256='.$signature]);if($response['status']<200||$response['status']>=300)throw new RuntimeException('Webhook returned HTTP '.$response['status'].'.');}
                // Acknowledgement or a real rendered version marker proves live;
                // accepting a webhook alone never marks a deployment live.
                $response=LifeOSHubHttp::send($site['url']);$marker='lifeos-version:'.$job['page'].':'.$job['version'];$verified=$response['status']>=200&&$response['status']<300&&str_contains($response['body'],$marker);
                $expired=!$verified&&time()-strtotime($job['created_at'].' UTC')>1800;
                $this->run("UPDATE hub_deployments SET delivery='sent',attempts=attempts+?,status=CASE WHEN status IN ('live','failed') THEN status ELSE ? END,next_attempt=?,locked_until=0,last_error=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",[$job['delivery']==='sent'?0:1,$verified?'live':($expired?'failed':'building'),time()+30,$expired?'No rendered-version confirmation was received within 30 minutes.':'',$job['id']]);
            }catch(Throwable){$attempt=(int)$job['attempts']+1;$failed=$attempt>=5;$this->run('UPDATE hub_deployments SET delivery=?,status=CASE WHEN status=\'live\' THEN status ELSE ? END,attempts=?,next_attempt=?,locked_until=0,last_error=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$failed?'failed':'retry',$failed?'failed':'queued',$attempt,time()+min(3600,30*(2**$attempt)),'Delivery or rendered-version verification failed.',$job['id']]);}
            $count++;
        }return $count;
    }
}
